package proctree

import (
	"encoding/json"
	"os"
	"os/exec"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestMain doubles as the helper process: when re-exec'd with
// PROCTREE_HELPER=1 it prints its own ancestors as JSON and exits, so tests
// can assert on the ancestry a real child process observes.
func TestMain(m *testing.M) {
	if os.Getenv("PROCTREE_HELPER") == "1" {
		refs := Ancestors(10)
		if err := json.NewEncoder(os.Stdout).Encode(refs); err != nil {
			os.Exit(1)
		}
		os.Exit(0)
	}
	os.Exit(m.Run())
}

func TestRef_Self(t *testing.T) {
	t.Parallel()
	ref, err := Ref(os.Getpid())
	require.NoError(t, err)
	assert.Equal(t, os.Getpid(), ref.PID)
	assert.NotZero(t, ref.StartTime, "a live process must have a resolvable start time")
}

func TestAncestors_FirstIsParent(t *testing.T) {
	t.Parallel()
	refs := Ancestors(10)
	require.NotEmpty(t, refs)
	assert.Equal(t, os.Getppid(), refs[0].PID)
	for _, r := range refs {
		assert.Positive(t, r.PID)
	}
}

// The identity contract this package exists for: a process spawned by this
// test sees this test process in its ancestry, with a start time that matches
// what this process resolves for itself — so pid+starttime is a stable
// cross-process identity for "the same live process".
func TestAncestors_ChildSeesParentIdentity(t *testing.T) {
	t.Parallel()
	self, err := Ref(os.Getpid())
	require.NoError(t, err)

	exe, err := os.Executable()
	require.NoError(t, err)
	cmd := exec.Command(exe)
	cmd.Env = append(os.Environ(), "PROCTREE_HELPER=1")
	out, err := cmd.Output()
	require.NoError(t, err, "helper process failed")

	var refs []ProcessRef
	require.NoError(t, json.Unmarshal(out, &refs))
	require.NotEmpty(t, refs)

	found := false
	for _, r := range refs {
		if r.SameProcess(self) {
			found = true
		}
	}
	assert.True(t, found, "child's ancestry must contain the parent's pid+starttime identity, got %+v (want %+v)", refs, self)
}

func TestSameProcess_RejectsPIDReuse(t *testing.T) {
	t.Parallel()
	a := ProcessRef{PID: 42, StartTime: 1000}
	b := ProcessRef{PID: 42, StartTime: 2000}
	assert.False(t, a.SameProcess(b), "same PID with a different start time is a recycled PID, not the same process")
	assert.True(t, a.SameProcess(ProcessRef{PID: 42, StartTime: 1000}))
}

// Package proctree resolves process ancestry with identity that survives PID
// reuse. A ProcessRef is a (PID, start time) pair: equal pairs name the same
// live process instance, because a recycled PID always comes with a new start
// time. Start-time units are platform-specific (microseconds since epoch on
// darwin, clock ticks since boot on linux, FILETIME on windows) — refs are
// only ever compared against refs recorded on the same machine, so the unit
// never needs to be interpreted, only compared.
package proctree

// ProcessRef identifies one live process instance.
type ProcessRef struct {
	PID       int    `json:"pid"`
	StartTime int64  `json:"start_time"`
	Exe       string `json:"exe,omitempty"`
}

// SameProcess reports whether both refs name the same process instance:
// same PID and same start time. Exe is informational and not compared.
func (r ProcessRef) SameProcess(o ProcessRef) bool {
	return r.PID == o.PID && r.StartTime == o.StartTime && r.PID != 0
}

// Ref resolves the ProcessRef for pid. Errors when the process does not
// exist or the platform refuses introspection.
func Ref(pid int) (ProcessRef, error) {
	return refOf(pid)
}

// Ancestors returns the current process's ancestors nearest-first (parent,
// grandparent, ...), at most max entries. The walk stops at the root
// (PID 0/1), on a cycle, or at the first resolution failure — partial
// results are returned, never an error: callers treat ancestry as
// best-effort evidence.
func Ancestors(max int) []ProcessRef {
	var refs []ProcessRef
	seen := map[int]bool{}
	pid := parentOf(currentPID())
	for pid > 1 && len(refs) < max && !seen[pid] {
		seen[pid] = true
		ref, err := refOf(pid)
		if err != nil {
			break
		}
		refs = append(refs, ref)
		pid = parentOf(pid)
	}
	return refs
}

package proctree

import (
	"fmt"
	"os"
	"strings"

	"golang.org/x/sys/unix"
)

func currentPID() int { return os.Getpid() }

func kinfo(pid int) (*unix.KinfoProc, error) {
	kp, err := unix.SysctlKinfoProc("kern.proc.pid", pid)
	if err != nil {
		return nil, fmt.Errorf("sysctl kern.proc.pid %d: %w", pid, err)
	}
	return kp, nil
}

func refOf(pid int) (ProcessRef, error) {
	kp, err := kinfo(pid)
	if err != nil {
		return ProcessRef{}, err
	}
	start := kp.Proc.P_starttime
	comm := kp.Proc.P_comm[:]
	n := 0
	for n < len(comm) && comm[n] != 0 {
		n++
	}
	exe := strings.ToValidUTF8(string(func() []byte {
		b := make([]byte, n)
		for i := 0; i < n; i++ {
			b[i] = byte(comm[i])
		}
		return b
	}()), "")
	return ProcessRef{
		PID:       pid,
		StartTime: start.Sec*1_000_000 + int64(start.Usec),
		Exe:       exe,
	}, nil
}

func parentOf(pid int) int {
	kp, err := kinfo(pid)
	if err != nil {
		return 0
	}
	return int(kp.Eproc.Ppid)
}

package proctree

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func currentPID() int { return os.Getpid() }

// statFields returns the fields of /proc/<pid>/stat AFTER the comm field.
// comm is parenthesized and may itself contain spaces and parentheses, so the
// only safe parse is from the LAST ')' — everything after it is
// space-separated. Returned slice index 0 is field 3 (state); ppid is field 4
// (index 1); starttime is field 22 (index 19).
func statFields(pid int) (comm string, fields []string, err error) {
	data, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
	if err != nil {
		return "", nil, fmt.Errorf("read /proc/%d/stat: %w", pid, err)
	}
	s := string(data)
	open := strings.IndexByte(s, '(')
	closeIdx := strings.LastIndexByte(s, ')')
	if open < 0 || closeIdx < open || closeIdx+2 > len(s) {
		return "", nil, fmt.Errorf("malformed /proc/%d/stat", pid)
	}
	return s[open+1 : closeIdx], strings.Fields(s[closeIdx+2:]), nil
}

func refOf(pid int) (ProcessRef, error) {
	comm, fields, err := statFields(pid)
	if err != nil {
		return ProcessRef{}, err
	}
	if len(fields) < 20 {
		return ProcessRef{}, fmt.Errorf("short /proc/%d/stat: %d fields", pid, len(fields))
	}
	start, err := strconv.ParseInt(fields[19], 10, 64)
	if err != nil {
		return ProcessRef{}, fmt.Errorf("parse starttime for pid %d: %w", pid, err)
	}
	return ProcessRef{PID: pid, StartTime: start, Exe: comm}, nil
}

func parentOf(pid int) int {
	_, fields, err := statFields(pid)
	if err != nil || len(fields) < 2 {
		return 0
	}
	ppid, err := strconv.Atoi(fields[1])
	if err != nil {
		return 0
	}
	return ppid
}

package proctree

import (
	"fmt"
	"os"

	"golang.org/x/sys/windows"
)

func currentPID() int { return os.Getpid() }

// snapshotEntry finds pid's row in a toolhelp process snapshot.
func snapshotEntry(pid int) (*windows.ProcessEntry32, error) {
	snap, err := windows.CreateToolhelp32Snapshot(windows.TH32CS_SNAPPROCESS, 0)
	if err != nil {
		return nil, fmt.Errorf("process snapshot: %w", err)
	}
	defer windows.CloseHandle(snap) //nolint:errcheck // read-only snapshot handle
	var entry windows.ProcessEntry32
	entry.Size = uint32(windows.SizeofProcessEntry32)
	for err := windows.Process32First(snap, &entry); err == nil; err = windows.Process32Next(snap, &entry) {
		if int(entry.ProcessID) == pid {
			e := entry
			return &e, nil
		}
	}
	return nil, fmt.Errorf("pid %d not in process snapshot", pid)
}

func refOf(pid int) (ProcessRef, error) {
	entry, err := snapshotEntry(pid)
	if err != nil {
		return ProcessRef{}, err
	}
	h, err := windows.OpenProcess(windows.PROCESS_QUERY_LIMITED_INFORMATION, false, uint32(pid))
	if err != nil {
		return ProcessRef{}, fmt.Errorf("open process %d: %w", pid, err)
	}
	defer windows.CloseHandle(h) //nolint:errcheck // query-only handle
	var creation, exit, kernel, user windows.Filetime
	if err := windows.GetProcessTimes(h, &creation, &exit, &kernel, &user); err != nil {
		return ProcessRef{}, fmt.Errorf("process times for %d: %w", pid, err)
	}
	return ProcessRef{
		PID:       pid,
		StartTime: int64(creation.HighDateTime)<<32 | int64(creation.LowDateTime),
		Exe:       windows.UTF16ToString(entry.ExeFile[:]),
	}, nil
}

func parentOf(pid int) int {
	entry, err := snapshotEntry(pid)
	if err != nil {
		return 0
	}
	return int(entry.ParentProcessID)
}

