// Package proctree resolves process ancestry with identity that survives PID
// reuse. A ProcessRef is a (PID, start time) pair: equal pairs name the same
// live process instance, because within one boot a recycled PID always comes
// with a new start time. On Linux the unit is boot-relative (clock ticks), so
// a cross-reboot collision is theoretically possible — callers treat ancestry
// as best-effort evidence, never proof. Start-time units are otherwise
// platform-specific (microseconds since epoch on darwin, FILETIME on
// windows); refs are only ever compared against refs recorded on the same
// machine, so the unit never needs to be interpreted, only compared.
package proctree

// ProcessRef identifies one live process instance.
type ProcessRef struct {
	PID       int    `json:"pid"`
	StartTime int64  `json:"start_time"`
	Exe       string `json:"exe,omitempty"`
}

// SameProcess reports whether both refs name the same process instance:
// same PID and same start time. Exe is informational and not compared.
func (r ProcessRef) SameProcess(o ProcessRef) bool {
	return r.PID == o.PID && r.StartTime == o.StartTime && r.PID != 0
}

// Ref resolves the ProcessRef for pid. Errors when the process does not
// exist or the platform refuses introspection.
func Ref(pid int) (ProcessRef, error) {
	ref, _, err := procInfo(pid)
	return ref, err
}

// Ancestors returns the current process's ancestors nearest-first (parent,
// grandparent, ...), at most limit entries. The walk stops at the root
// (PID 0/1), on a cycle, or at the first resolution failure — partial
// results are returned, never an error: callers treat ancestry as
// best-effort evidence. Each level costs one platform introspection call
// (procInfo returns the ref and its parent PID together).
func Ancestors(limit int) []ProcessRef {
	var refs []ProcessRef
	seen := map[int]bool{}
	pid := currentPPID()
	for pid > 1 && len(refs) < limit && !seen[pid] {
		seen[pid] = true
		ref, ppid, err := procInfo(pid)
		if err != nil {
			break
		}
		refs = append(refs, ref)
		pid = ppid
	}
	return refs
}

package proctree

import (
	"fmt"
	"os"
	"strings"

	"golang.org/x/sys/unix"
)

func currentPPID() int { return os.Getppid() }

// procInfo resolves pid's ref and parent PID in a single sysctl.
func procInfo(pid int) (ProcessRef, int, error) {
	kp, err := unix.SysctlKinfoProc("kern.proc.pid", pid)
	if err != nil {
		return ProcessRef{}, 0, fmt.Errorf("sysctl kern.proc.pid %d: %w", pid, err)
	}
	start := kp.Proc.P_starttime
	comm := kp.Proc.P_comm[:]
	n := 0
	for n < len(comm) && comm[n] != 0 {
		n++
	}
	b := make([]byte, n)
	for i := range n {
		b[i] = comm[i]
	}
	ref := ProcessRef{
		PID:       pid,
		StartTime: start.Sec*1_000_000 + int64(start.Usec),
		Exe:       strings.ToValidUTF8(string(b), ""),
	}
	return ref, int(kp.Eproc.Ppid), nil
}

package proctree

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func currentPPID() int { return os.Getppid() }

// procInfo resolves pid's ref and parent PID from one /proc/<pid>/stat read.
//
// comm is parenthesized and may itself contain spaces and parentheses, so the
// only safe parse is from the LAST ')' — everything after it is
// space-separated. In the post-comm fields, index 1 is ppid (stat field 4)
// and index 19 is starttime (stat field 22, clock ticks since boot).
func procInfo(pid int) (ProcessRef, int, error) {
	data, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
	if err != nil {
		return ProcessRef{}, 0, fmt.Errorf("read /proc/%d/stat: %w", pid, err)
	}
	s := string(data)
	open := strings.IndexByte(s, '(')
	closeIdx := strings.LastIndexByte(s, ')')
	if open < 0 || closeIdx < open || closeIdx+2 > len(s) {
		return ProcessRef{}, 0, fmt.Errorf("malformed /proc/%d/stat", pid)
	}
	comm := s[open+1 : closeIdx]
	fields := strings.Fields(s[closeIdx+2:])
	if len(fields) < 20 {
		return ProcessRef{}, 0, fmt.Errorf("short /proc/%d/stat: %d fields", pid, len(fields))
	}
	ppid, err := strconv.Atoi(fields[1])
	if err != nil {
		return ProcessRef{}, 0, fmt.Errorf("parse ppid for pid %d: %w", pid, err)
	}
	start, err := strconv.ParseInt(fields[19], 10, 64)
	if err != nil {
		return ProcessRef{}, 0, fmt.Errorf("parse starttime for pid %d: %w", pid, err)
	}
	return ProcessRef{PID: pid, StartTime: start, Exe: comm}, ppid, nil
}

package proctree

import (
	"fmt"
	"os"
	"unsafe"

	"golang.org/x/sys/windows"
)

func currentPPID() int { return os.Getppid() }

// procInfo resolves pid's ref and parent PID with one toolhelp snapshot scan
// plus one OpenProcess for the creation time.
func procInfo(pid int) (ProcessRef, int, error) {
	snap, err := windows.CreateToolhelp32Snapshot(windows.TH32CS_SNAPPROCESS, 0)
	if err != nil {
		return ProcessRef{}, 0, fmt.Errorf("process snapshot: %w", err)
	}
	defer windows.CloseHandle(snap) //nolint:errcheck // read-only snapshot handle
	var entry windows.ProcessEntry32
	entry.Size = uint32(unsafe.Sizeof(entry))
	found := false
	for err := windows.Process32First(snap, &entry); err == nil; err = windows.Process32Next(snap, &entry) {
		if int(entry.ProcessID) == pid {
			found = true
			break
		}
	}
	if !found {
		return ProcessRef{}, 0, fmt.Errorf("pid %d not in process snapshot", pid)
	}

	h, err := windows.OpenProcess(windows.PROCESS_QUERY_LIMITED_INFORMATION, false, uint32(pid))
	if err != nil {
		return ProcessRef{}, 0, fmt.Errorf("open process %d: %w", pid, err)
	}
	defer windows.CloseHandle(h) //nolint:errcheck // query-only handle
	var creation, exit, kernel, user windows.Filetime
	if err := windows.GetProcessTimes(h, &creation, &exit, &kernel, &user); err != nil {
		return ProcessRef{}, 0, fmt.Errorf("process times for %d: %w", pid, err)
	}
	ref := ProcessRef{
		PID:       pid,
		StartTime: int64(creation.HighDateTime)<<32 | int64(creation.LowDateTime),
		Exe:       windows.UTF16ToString(entry.ExeFile[:]),
	}
	return ref, int(entry.ParentProcessID), nil
}

